    int i = 3, k = 1;
    switch(i) {
      case 1: k++;
      case 2: k += 3;
      case 3: k = 0;
      case 4: k += 3;
      case 5: k -= 10;
      default: k--;
    }
    System.out.print(k);
  }
}

#include <stdio.h>
int main() {
  int i, j;
  i = 10; j = 20;
  if(i > 10 && j++ > 20) i = i + 1;
  else i = i - 1;
  printf("%d, %d", i, j);
  return 0;
}

#include <stdio.h>
int main() {
  int i = 5, j = 10, k = 15;
  if (i > 5 || j > 5) {
    k = i + j;
  } else {
    k = i * j;
  }
  printf("%d", k);
  return 0;
}

#include <stdio.h>
int main() {
  int a = 10, b = 20;
  int *p = &a;
